Problem:
A tutoring company hires full-time tutors and supplements with assistant tutors from a nearby high school. Every day, full-time tutors work 8 hours and get paid $650 while assistant tutors work 4 hours and get paid $120. During Christmas break, the tutoring company expects more interest and plans to require 1200 hours of teaching availability. If the tutoring company has a budget of $55000, how many tutors and assistant tutors should be hired to minimize the amount of staff?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "full-time tutors",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "assistant tutors",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "full-time tutors",
     "coef": 1.0
    },
    {
     "var": "assistant tutors",
     "coef": 1.0
    }
   ]
  },
  "constraints": [
   {
    "name": "teaching hours",
    "terms": [
     {
      "var": "full-time tutors",
      "coef": 8.0
     },
     {
      "var": "assistant tutors",
      "coef": 4.0
     }
    ],
    "sense": ">=",
    "rhs": 1200.0
   },
   {
    "name": "budget",
    "terms": [
     {
      "var": "full-time tutors",
      "coef": 650.0
     },
     {
      "var": "assistant tutors",
      "coef": 120.0
     }
    ],
    "sense": "<=",
    "rhs": 55000.0
   }
  ]
 },
 "facts": {
  "objective": 254.0,
  "values": {
   "full-time tutors": 46.0,
   "assistant tutors": 208.0
  },
  "binding": [
   "teaching hours"
  ],
  "slack": {
   "teaching hours": 0.0,
   "budget": 140.0
  },
  "shadow_prices": null
 }
}
